<?php
if (!defined('ABSPATH')) exit;
function gim_normalize_estimate_items($items){ $out=[];$service=0;$materials=0; foreach((array)$items as $i){ $type=sanitize_key($i['type']??'labour'); if(!in_array($type,['labour','callout','emergency','material','other_service'],true))continue; $qty=max(1,(int)($i['quantity']??1)); $unit=max(0,(int)($i['unit_pence']??0)); $line=$qty*$unit; $is_mat=$type==='material'; if($is_mat)$materials+=$line; else $service+=$line; $out[]=['type'=>$type,'label'=>sanitize_text_field($i['label']??ucfirst($type)),'quantity'=>$qty,'unit_pence'=>$unit,'line_pence'=>$line,'commissionable'=>!$is_mat]; } return ['items'=>$out,'service'=>$service,'materials'=>$materials,'total'=>$service+$materials]; }
function gim_create_estimate($job_id,$provider_user_id,$items){ global $wpdb; $p=gim_provider_profile($provider_user_id); $job=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE id=%d',$job_id)); if(!$job||!$p||(int)$job->provider_id!==(int)$p->id||!in_array($job->status,['provider_accepted','estimate_sent'],true))return new WP_Error('forbidden','Cannot estimate this job.'); $n=gim_normalize_estimate_items($items); if($n['service']<=0)return new WP_Error('amount','Service amount required.'); $rev=1+(int)$wpdb->get_var($wpdb->prepare('SELECT COALESCE(MAX(revision_no),0) FROM '.gim_table('estimates').' WHERE job_id=%d',$job_id)); $ref=gim_ref('GM-EST'); $digest=hash('sha256',gim_json([$job_id,$p->id,$rev,$n])); $wpdb->insert(gim_table('estimates'),['reference'=>$ref,'job_id'=>$job_id,'provider_id'=>$p->id,'status'=>'sent','revision_no'=>$rev,'items_json'=>gim_json($n['items']),'service_subtotal_pence'=>$n['service'],'materials_subtotal_pence'=>$n['materials'],'total_pence'=>$n['total'],'digest'=>$digest,'created_at'=>gim_now()]); $wpdb->update(gim_table('jobs'),['status'=>'estimate_sent','updated_at'=>gim_now()],['id'=>$job_id]); gim_audit('estimate.sent','estimate',$ref,['job'=>$job->reference]); return $wpdb->insert_id; }
function gim_customer_decide_estimate($estimate_id,$customer_id,$decision){ global $wpdb; $e=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('estimates').' WHERE id=%d',$estimate_id)); if(!$e||$e->status!=='sent')return new WP_Error('estimate','Estimate unavailable.'); $job=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE id=%d',$e->job_id)); if(!$job||!gim_job_owned_by_customer($job,$customer_id))return new WP_Error('forbidden','Forbidden.'); if($decision==='accept'){ $wpdb->update(gim_table('estimates'),['status'=>'accepted','decided_at'=>gim_now()],['id'=>$e->id]); $wpdb->update(gim_table('jobs'),['status'=>'payment_required','updated_at'=>gim_now()],['id'=>$job->id]); }elseif($decision==='reject'){ $wpdb->update(gim_table('estimates'),['status'=>'rejected','decided_at'=>gim_now()],['id'=>$e->id]); $wpdb->update(gim_table('jobs'),['status'=>'provider_accepted','updated_at'=>gim_now()],['id'=>$job->id]); }else return new WP_Error('decision','Invalid decision.'); gim_audit('estimate.'.$decision.'ed','estimate',$e->reference); return true; }
